#!/bin/bash

# Common Functions.
printVersion() {
    echo '0.18.0-alpha.6'
}
RCM_VERSION=`printVersion`

source=$RCM_LIB/functions/common/echo.sh; [ -f "$source" ] && source "$source" || exit 1

# Parse arguments. Generated by parse-options.sh.
_new_arguments=()
while [[ $# -gt 0 ]]; do
    case "$1" in
        --help) help=1; shift ;;
        --version) version=1; shift ;;
        --[^-]*) shift ;;
        *) _new_arguments+=("$1"); shift ;;
    esac
done
set -- "${_new_arguments[@]}"
unset _new_arguments

# Define variables and constants.
RCM_INDENT='    '; [ "$(tput cols)" -le 80 ] && RCM_INDENT='  '

# Functions. Help and Version.
usage() {
    title RCM System RAM Swap
    _ 'Variation '; yellow 4G; _.
    _ 'Version '; yellow `printVersion`; _.
    _.
cat << EOF
Usage: rcm-system-ram-swap-4gb [options]

Global Options:
   --fast
        No delay every subtask.
   --version
        Print version of this script.
   --help
        Show this help.
EOF
}

# Help and Version.
[ -n "$help" ] && { usage; exit 1; }
[ -n "$version" ] && { printVersion; exit 1; }

# Title.
title rcm-system-ram-swap-4gb
____

[ "$EUID" -ne 0 ] && { error This script needs to be run with superuser privileges.; x; }

# Dependency.
while IFS= read -r line; do
    [[ -z "$line" ]] || command -v `cut -d: -f1 <<< "${line}"` >/dev/null || { error Unable to proceed, command not found: '`'`cut -d: -f1 <<< "${line}"`'`'.; x; }
done <<< `usage 2>/dev/null | sed -n '/^Dependency:/,$p' | sed -n '2,/^\s*$/p' | sed 's/^ *//g'`

path=/swapfile-rcm-4G

chapter Membuat file swap.
code fallocate -l 4G "$path"
code chmod 600 "$path"
code mkswap "$path"
____

if [ ! -f "$path" ];then
    fallocate -l 4G "$path"
    chmod 600 "$path"
    mkswap "$path"
fi
chapter Mengaktifkan file swap.
if grep -q "^${path}$" <<< `swapon --show=name --noheadings --raw`;then
    code swapon "$path"
else
    code swapon "$path"
    swapon "$path"
fi
____

exit 0

